form.noValidate = true;
form.addEventListener('submit', (e) => {
  if (!form.checkValidity()) {
    e.preventDefault();
    const bad = form.querySelector(':invalid');
    bad.setAttribute('aria-invalid', 'true');
    errorBox.textContent = bad.validationMessage;
    bad.focus();
  }
});

