function safeUrl(v) {
  try {
    const u = new URL(v, location.origin);
    return ['http:', 'https:', 'mailto:'].includes(u.protocol) ? u.href : '#';
  } catch {
    return '#';
  }
}
safeUrl('javascript:alert(1)'); // '#'
